PRAGMA foreign_keys=ON;
CREATE TABLE target_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE domains(domain TEXT PRIMARY KEY,status TEXT NOT NULL,selected_sources INTEGER NOT NULL DEFAULT 0,records INTEGER NOT NULL DEFAULT 0,typed_records INTEGER NOT NULL DEFAULT 0);
CREATE TABLE source_snapshots(domain TEXT NOT NULL,source_key TEXT NOT NULL,source_version TEXT NOT NULL,provider TEXT,physical_origin TEXT,status TEXT NOT NULL,fingerprint_json TEXT NOT NULL,PRIMARY KEY(domain,source_key,source_version),FOREIGN KEY(domain) REFERENCES domains(domain));
CREATE TABLE copy_cursors(domain TEXT NOT NULL,source_key TEXT NOT NULL,source_version TEXT NOT NULL,last_record_id TEXT,complete INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(domain,source_key,source_version));
CREATE TABLE source_records(uid TEXT PRIMARY KEY,domain TEXT NOT NULL,source_key TEXT NOT NULL,source_version TEXT NOT NULL,record_id TEXT NOT NULL,content_sha256 TEXT NOT NULL,record_kind TEXT,provider TEXT,physical_origin TEXT,source_family TEXT,source_scope_json TEXT,source_native_id_json TEXT,household_scope_json TEXT,UNIQUE(domain,source_key,source_version,record_id),FOREIGN KEY(domain,source_key,source_version) REFERENCES source_snapshots(domain,source_key,source_version));
CREATE INDEX record_lookup ON source_records(domain,source_key,source_version,record_id);
CREATE INDEX family_lookup ON source_records(domain,source_family,source_scope_json,record_id);
CREATE TABLE recipe_headers(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),title_json TEXT,language_json TEXT,yield_json TEXT,steps_json TEXT);
CREATE TABLE ingredient_mentions(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),recipe_id TEXT,ordinal INTEGER,raw_text_json TEXT,quantity_json TEXT,unit_json TEXT,identity_status TEXT NOT NULL);
CREATE TABLE ingredient_entities(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),native_id_json TEXT,name_json TEXT,identity_status TEXT NOT NULL);
CREATE TABLE menu_entries(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),entry_kind TEXT NOT NULL,title_json TEXT,source_scope_json TEXT,source_native_id_json TEXT);
CREATE TABLE barcode_products(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),native_id_json TEXT,identity_status TEXT NOT NULL);
CREATE TABLE external_store_references(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),reference_json TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE dietary_assertions(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),assertion_kind TEXT,source_record_id_json TEXT,facts_json TEXT NOT NULL,numeric_lexemes_json TEXT);
CREATE TABLE supplier_entities(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),entity_id_json TEXT,entity_kind TEXT,name_json TEXT);
CREATE TABLE supplier_assertions(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),subject_id_json TEXT,assertion_kind TEXT NOT NULL,assertion_json TEXT NOT NULL);
CREATE TABLE evidence_citations(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),citation_json TEXT NOT NULL,attachment_status TEXT NOT NULL);
CREATE TABLE household_profiles(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),scope_json TEXT,profile_json TEXT NOT NULL,scope_status TEXT NOT NULL);
CREATE TABLE inventory_lots(record_uid TEXT PRIMARY KEY REFERENCES source_records(uid),scope_json TEXT,item_id_json TEXT,quantity_json TEXT,unit_json TEXT,scope_status TEXT NOT NULL);
CREATE TABLE identifier_claims(record_uid TEXT NOT NULL REFERENCES source_records(uid),namespace TEXT NOT NULL,provider TEXT NOT NULL,source_key TEXT NOT NULL,source_version TEXT NOT NULL,value_type TEXT NOT NULL,lexical_value TEXT NOT NULL,json_pointer TEXT NOT NULL,contract TEXT NOT NULL,PRIMARY KEY(record_uid,namespace,json_pointer));
CREATE INDEX identifier_lookup ON identifier_claims(namespace,provider,source_key,source_version,value_type,lexical_value);
CREATE TABLE relation_claims(owner_uid TEXT NOT NULL REFERENCES source_records(uid),ordinal INTEGER NOT NULL,kind TEXT NOT NULL,target_domain TEXT,target_id_json TEXT,detail_json TEXT NOT NULL,PRIMARY KEY(owner_uid,ordinal));
CREATE TABLE relation_resolutions(owner_uid TEXT NOT NULL,ordinal INTEGER NOT NULL,contract TEXT NOT NULL,disposition TEXT NOT NULL CHECK(disposition IN ('resolved','missing','ambiguous','deferred')),reason TEXT NOT NULL,candidate_count INTEGER NOT NULL,lookup_json TEXT NOT NULL,PRIMARY KEY(owner_uid,ordinal),FOREIGN KEY(owner_uid,ordinal) REFERENCES relation_claims(owner_uid,ordinal));
CREATE TABLE relation_candidates(owner_uid TEXT NOT NULL,ordinal INTEGER NOT NULL,target_uid TEXT NOT NULL REFERENCES source_records(uid),PRIMARY KEY(owner_uid,ordinal,target_uid),FOREIGN KEY(owner_uid,ordinal) REFERENCES relation_claims(owner_uid,ordinal));
CREATE INDEX relation_kinds ON relation_claims(kind,owner_uid);
CREATE INDEX resolution_disposition ON relation_resolutions(disposition);
CREATE INDEX candidate_targets ON relation_candidates(target_uid,owner_uid);
CREATE VIEW resolved_links AS SELECT r.owner_uid,r.ordinal,c.kind,c.target_domain,t.target_uid,r.contract FROM relation_resolutions r JOIN relation_claims c USING(owner_uid,ordinal) JOIN relation_candidates t USING(owner_uid,ordinal) WHERE r.disposition='resolved';
CREATE VIEW recipe_ingredient_links AS SELECT l.owner_uid AS recipe_uid,l.target_uid AS ingredient_uid FROM resolved_links l WHERE l.kind='has_ingredient_mention';
CREATE VIEW menu_member_links AS SELECT owner_uid AS menu_uid,target_uid AS member_uid FROM resolved_links WHERE kind='contains_menu_entry' UNION SELECT target_uid,owner_uid FROM resolved_links WHERE kind IN ('item_of','section_of');
CREATE VIEW citation_links AS SELECT owner_uid AS record_uid,target_uid AS citation_uid FROM resolved_links WHERE kind='cites' UNION SELECT target_uid,owner_uid FROM resolved_links WHERE kind='cites_record';
CREATE VIEW supplier_ownership_links AS SELECT l.*,COALESCE(s.record_uid,subject.target_uid) AS subject_uid,COALESCE(s.entity_id_json,a.subject_id_json) AS owner_native_id,t.entity_id_json AS target_native_id FROM resolved_links l LEFT JOIN supplier_entities s ON s.record_uid=l.owner_uid LEFT JOIN supplier_assertions a ON a.record_uid=l.owner_uid LEFT JOIN resolved_links subject ON subject.owner_uid=l.owner_uid AND subject.kind='assertion_subject' JOIN supplier_entities t ON t.record_uid=l.target_uid WHERE l.kind IN ('owned_by','parent_organization','subsidiary') AND (s.record_uid IS NOT NULL OR subject.target_uid IS NOT NULL);
CREATE VIEW unresolved_links AS SELECT c.*,r.contract,r.disposition,r.reason,r.candidate_count,r.lookup_json FROM relation_claims c JOIN relation_resolutions r USING(owner_uid,ordinal) WHERE disposition!='resolved';
